package dev.pocketengine.features.memory;

import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;

public final class ConversationMemoryReceiptTest {
    private static final String ID="11111111-1111-1111-1111-111111111111",OTHER="22222222-2222-2222-2222-222222222222";
    private JSONObject proposal(String action)throws Exception{return new JSONObject().put("action",action).put("target",new JSONObject().put("id",ID).put("revision",7));}
    private JSONObject saved(String action)throws Exception{return new JSONObject().put("action",action).put("status","saved").put("accepted",true).put("mutationApplied",true).put("formalMemorySaved",!action.equals("forget"));}
    private JSONObject record(String action,String id,long revision)throws Exception{return saved(action).put("record",new JSONObject().put("id",id).put("revision",revision));}
    @Test public void createRequiresOneNewFormalRevision()throws Exception {ConversationMemoryReceipt.require(proposal("create"),record("create",ID,1));assertThrows(SecurityException.class,()->ConversationMemoryReceipt.require(proposal("create"),record("create",ID,2)));assertThrows(SecurityException.class,()->ConversationMemoryReceipt.require(proposal("create"),record("create","unknown",1)));}
    @Test public void correctionRequiresTheExactReviewedRecordAndNextRevision()throws Exception {ConversationMemoryReceipt.require(proposal("update"),record("update",ID,8));assertThrows(SecurityException.class,()->ConversationMemoryReceipt.require(proposal("update"),record("update",OTHER,8)));for(int revision:new int[]{7,9})assertThrows(SecurityException.class,()->ConversationMemoryReceipt.require(proposal("update"),record("update",ID,revision)));}
    @Test public void forgetIsAnAppliedDeletionNeverASavedFormalMemory()throws Exception {ConversationMemoryReceipt.require(proposal("forget"),saved("forget").put("deleted",2));assertThrows(SecurityException.class,()->ConversationMemoryReceipt.require(proposal("forget"),saved("forget").put("deleted",0)));assertThrows(SecurityException.class,()->ConversationMemoryReceipt.require(proposal("forget"),saved("forget").put("deleted",1).put("formalMemorySaved",true)));assertThrows(SecurityException.class,()->ConversationMemoryReceipt.require(proposal("forget"),record("forget",ID,8).put("deleted",1)));}
    @Test public void unknownPreservesAllThreeUnknownFactsIncludingExplicitNulls()throws Exception {JSONObject unknown=new JSONObject().put("action","update").put("status","unknown").put("accepted",JSONObject.NULL).put("mutationApplied",JSONObject.NULL).put("formalMemorySaved",JSONObject.NULL);ConversationMemoryReceipt.require(proposal("update"),unknown);for(String key:new String[]{"accepted","mutationApplied","formalMemorySaved"}){JSONObject changed=new JSONObject(unknown.toString()).put(key,false);assertThrows(SecurityException.class,()->ConversationMemoryReceipt.require(proposal("update"),changed));JSONObject missing=new JSONObject(unknown.toString());missing.remove(key);assertThrows(SecurityException.class,()->ConversationMemoryReceipt.require(proposal("update"),missing));}}
    @Test public void rejectionCannotReportAnAppliedMutation()throws Exception {JSONObject rejected=new JSONObject().put("action","create").put("status","rejected").put("accepted",false).put("mutationApplied",false).put("formalMemorySaved",false);ConversationMemoryReceipt.require(proposal("create"),rejected);assertThrows(SecurityException.class,()->ConversationMemoryReceipt.require(proposal("create"),rejected.put("mutationApplied",true)));}
    @Test public void actionAndIntegralRevisionCannotBeChangedByTheReceipt()throws Exception {assertThrows(SecurityException.class,()->ConversationMemoryReceipt.require(proposal("update"),record("create",ID,1)));JSONObject decimal=record("update",ID,8);decimal.getJSONObject("record").put("revision",8.0);assertThrows(SecurityException.class,()->ConversationMemoryReceipt.require(proposal("update"),decimal));assertThrows(ArithmeticException.class,()->ConversationMemoryReceipt.require(proposal("update").put("target",new JSONObject().put("id",ID).put("revision",Long.MAX_VALUE)),record("update",ID,1)));}
}
